import 'package:flutter_test/flutter_test.dart'; import 'package:safehelm/models/contact.dart'; import 'package:safehelm/services/contact_book.dart';
EmergencyContact c(String name,String phone,{bool enabled=true})=>EmergencyContact(name:name,phone:phone,enabled:enabled,priority:1);
void main(){test('adds, normalizes and persists in-memory contact data',(){final b=ContactBook([]);b.add(c('Mom','+91 99999-99999'));expect(b.contacts.single.normalizedPhone,'+919999999999');});test('rejects invalid and duplicate contacts',(){final b=ContactBook([c('Mom','+919999999999')]);expect(b.validate(c('Bad','x')),isNotNull);expect(b.validate(c('Again','+91 99999 99999')),isNotNull);});test('edits, toggles, deletes and reorders priority',(){final b=ContactBook([c('Mom','+911111111111'),c('Dad','+912222222222')]);b.replace(0,c('Mother','+913333333333'));b.setEnabled(0,false);b.remove(1);expect(b.contacts.single.name,'Mother');expect(b.contacts.single.enabled,false);expect(b.contacts.single.priority,1);});test('limits contacts to five',(){final b=ContactBook(List.generate(5,(i)=>c('C$i','+91999999999$i')));expect(b.validate(c('Six','+918888888888')),isNotNull);});}
